## 2️⃣ JavaScript – initialise the map

```js
// -------------------------------------------------------------------
// 2️⃣ Initialise MapLibre
// -------------------------------------------------------------------
const map = new maplibregl.Map({
  container: 'map',
  style: {
    version: 8,
    sources: {
      // A simple raster basemap – replace with your own style if you have one
      osm: {
        type: 'raster',
        tiles: [
          'https://{a-c}.tile.openstreetmap.org/{z}/{x}/{y}.png'
        ],
        tileSize: 256,
        attribution: '&copy; OpenStreetMap contributors'
      }
    },
    layers: [
      { id: 'osm', type: 'raster', source: 'osm' }
    ]
  },
  center: [0, 0],          // start somewhere – adjust to your data
  zoom: 2,
  hash: true
});
```

---

## 3️⃣ Load **all** SVG icons into the map

> **Why a loop?**  
> MapLibre needs each icon registered with `map.addImage(name, image, { sdf: true })`.  
> The example assumes your SVG files are named exactly like the `category` values (e.g. `cafe.svg`, `library.svg`).  
> If you need a prefix/suffix, just adjust the `iconName` construction.

```js
// -------------------------------------------------------------------
// 3️⃣ Load the 40+ SVG icons
// -------------------------------------------------------------------

// 1️⃣ List of all categories (you can generate this list server‑side)
//    – keep it in the same order as the files on disk.
const categories = [
  'cafe', 'library', 'restaurant', 'park', 'museum',
  // … add the rest of your 40 categories here …
];

// Helper: fetch an SVG, turn it into an ImageBitmap (works for SVG too)
function loadSvgAsImage(url) {
  return fetch(url)
    .then(r => r.blob())
    .then(blob => createImageBitmap(blob));
}

// Load every icon and register it with the map
function registerIcons() {
  const promises = categories.map(cat => {
    const url = `https://example.com/icons/${cat}.svg`; // <-- change to your domain
    return loadSvgAsImage(url).then(img => {
      // `sdf: true` lets you tint the icon with `icon-color` later (optional)
      map.addImage(cat, img, { sdf: true });
    });
  });

  return Promise.all(promises);
}
```

---

## 4️⃣ Add the **GeoJSON source** (5 000 venues)

```js
// -------------------------------------------------------------------
// 4️⃣ Add the venues source
// -------------------------------------------------------------------
function addVenueSource() {
  // Replace this URL with the real endpoint that returns your GeoJSON.
  const geojsonUrl = 'https://example.com/data/venues.geojson';

  map.addSource('venues', {
    type: 'geojson',
    data: geojsonUrl,
    // Optional: enable client‑side clustering for *very* dense zoom levels.
    // This does **not** affect the symbol layer – it only gives us a fallback
    // cluster layer when icons would otherwise be hidden.
    cluster: true,
    clusterRadius: 50,
    clusterMaxZoom: 14
  });
}
```

---

## 5️⃣ Symbol layer – show the correct icon per venue

```js
// -------------------------------------------------------------------
// 5️⃣ Symbol layer (the actual icons)
// -------------------------------------------------------------------
function addVenueLayer() {
  map.addLayer({
    id: 'venue-icons',
    type: 'symbol',
    source: 'venues',
    // Do **not** draw clusters with this layer – they have no `category`.
    filter: ['!', ['has', 'point_count']],
    layout: {
      // The icon name is exactly the category string.
      // If you need a prefix/suffix, use an expression like:
      //   ['concat', ['get', 'category'], '-icon']
      'icon-image': ['get', 'category'],

      // Scale icons with zoom (optional, tweak to taste)
      'icon-size': [
        'interpolate',
        ['linear'],
        ['zoom'],
        5, 0.5,   // at zoom 5 → 50 % size
        10, 1.0,  // at zoom 10 → 100 % size
        15, 1.5   // at zoom 15 → 150 % size
      ],

      // Keep icons upright when the map is pitched/rotated
      'icon-rotate': 0,
      'icon-pitch-alignment': 'map',
      'icon-rotation-alignment': 'map',

      // Do **not** allow icons to overlap.  If an icon cannot be placed,
      // it will be omitted (instead of stacking on top of another).
      'icon-allow-overlap': false,
      'icon-ignore-placement': false,
      // If an icon cannot be placed, just skip it – this prevents a huge
      // “pile‑up” of icons at low zoom.
      'icon-optional': true
    },
    paint: {
      // Optional: tint all icons with a single colour (requires `sdf:true` above)
      // 'icon-color': '#ff6600',
      // Optional: add a subtle halo so icons stay visible on any basemap
      // 'icon-halo-color': '#fff',
      // 'icon-halo-width': 1
    }
  });
}
```

---

## 6️⃣ (Optional) A **cluster fallback** layer

When the map is zoomed far out the `icon-optional: true` rule will hide many points, leaving the map empty.  
A tiny cluster layer gives the user a visual cue that there *are* many venues in that area.

```js
function addClusterLayer() {
  map.addLayer({
    id: 'venue-clusters',
    type: 'circle',
    source: 'venues',
    filter: ['has', 'point_count'],
    paint: {
      // Small, semi‑transparent circles
      'circle-radius': [
        'step',
        ['get', 'point_count'],
        10,   // 0‑9 points → radius 10
        100, 15, // 10‑99 points → radius 15
        500, 20  // 100+ points → radius 20
      ],
      'circle-color': '#888',
      'circle-opacity': 0.4
    }
  });

  // Optional: a label with the count
  map.addLayer({
    id: 'venue-cluster-count',
    type: 'symbol',
    source: 'venues',
    filter: ['has', 'point_count'],
    layout: {
      'text-field': '{point_count_abbreviated}',
      'text-font': ['Open Sans Bold', 'Arial Unicode MS Bold'],
      'text-size': 12
    },
    paint: {
      'text-color': '#fff'
    }
  });
}
```

---

## 7️⃣ Wire everything together – **wait for the map to be ready**

```js
// -------------------------------------------------------------------
// 7️⃣ Bootstrap – load icons → add source → add layers
// -------------------------------------------------------------------
map.once('load', () => {
  // 1️⃣ Load all SVG icons first
  registerIcons()
    .then(() => {
      console.log('✅ All icons loaded');
      // 2️⃣ Add the GeoJSON source
      addVenueSource();

      // 3️⃣ Add the symbol layer (icons)
      addVenueLayer();

      // 4️⃣ (Optional) add a cluster layer for very dense zoom levels
      addClusterLayer();
    })
    .catch(err => {
      console.error('❌ Failed to load icons', err);
    });
});
```

---

## 🎉 What you get

| Zoom level | What you see |
|------------|--------------|
| **Low (0‑5)** | Small, non‑overlapping icons (or the tiny cluster circles if the density is too high). |
| **Medium (6‑12)** | Icons appear at their natural size, still never overlapping. |
| **High (13‑22)** | Full‑size icons, one per venue, with optional colour‑tinting. |

You can further tweak the following parameters to suit your design:

| Parameter | Typical values | Effect |
|-----------|----------------|--------|
| `icon-size` | `['interpolate', ['linear'], ['zoom'], 5, 0.4, 12, 1]` | Scale icons with zoom. |
| `icon-allow-overlap` | `false` (default) | Prevents stacking. |
| `icon-optional` | `true` (default) | Hides an icon if it cannot be placed without overlap. |
| `clusterRadius` | `30‑80` | How far apart points must be to form a cluster. |
| `clusterMaxZoom` | `14` | Zoom level at which clustering stops (you can raise it if you want clusters deeper). |
| `icon-color` (requires `sdf:true`) | `'#ff6600'` | Tint all icons with a single colour. |
| `icon-halo-*` | `'#fff', 1` | Adds a halo for better contrast on busy basemaps. |

