## 1️⃣ HTML skeleton

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>MapLibre – 5 000 venues with category icons</title>
  <meta name="viewport" content="width=device-width, initial-scale=1.0">

  <!-- MapLibre GL JS v6 (replace with the exact version you need) -->
  <link href="https://unpkg.com/maplibre-gl@6.1.0/dist/maplibre-gl.css" rel="stylesheet"/>
  <script src="https://unpkg.com/maplibre-gl@6.1.0/dist/maplibre-gl.js"></script>

  <style>
    body, html { margin:0; padding:0; height:100%; }
    #map { position:absolute; top:0; bottom:0; width:100%; }
  </style>
</head>
<body>
<div id="map"></div>

<script>
  // --------------------------------------------------------------
  // 2️⃣ MAP INITIALISATION
  // --------------------------------------------------------------
  const map = new maplibregl.Map({
    container: 'map',
    style: {
      version: 8,
      sources: {
        // a simple raster basemap – replace with your own style if you have one
        "osm": {
          type: "raster",
          tiles: [
            "https://a.tile.openstreetmap.org/{z}/{x}/{y}.png",
            "https://b.tile.openstreetmap.org/{z}/{x}/{y}.png",
            "https://c.tile.openstreetmap.org/{z}/{x}/{y}.png"
          ],
          tileSize: 256,
          attribution: "© OpenStreetMap contributors"
        }
      },
      layers: [
        { id: "osm", type: "raster", source: "osm" }
      ]
    },
    center: [0, 0],   // set to your area of interest
    zoom: 2,
    hash: true
  });

  // --------------------------------------------------------------
  // 3️⃣ ICON LOADING
  // --------------------------------------------------------------
  // 3‑a. List of all category names (must match the `category` property
  //      in the GeoJSON).  The file name on the server is `${cat}.svg`.
  const categories = [
    "restaurant", "cafe", "bar", "museum", "park",
    "hotel", "shop", "bank", "pharmacy", "school",
    // … add the rest of your 40+ categories here …
  ];

  // 3‑b. Helper that returns a Promise that resolves when the image is added.
  function loadSvgIcon(cat) {
    const url = `https://my-cdn.example.com/icons/${cat}.svg`;
    return new Promise((resolve, reject) => {
      map.loadImage(url, (error, image) => {
        if (error) {
          console.error(`Failed to load ${url}`, error);
          reject(error);
          return;
        }
        // The image name we register is exactly the category string.
        // This lets us use ['get', 'category'] later.
        map.addImage(cat, image, { sdf: true }); // `sdf:true` lets you tint the SVG with `icon-color`
        resolve();
      });
    });
  }

  // 3‑c. Load *all* icons before we add the data layer.
  const iconPromises = categories.map(loadSvgIcon);

  // --------------------------------------------------------------
  // 4️⃣ GEOJSON SOURCE (5 000 venues)
  // --------------------------------------------------------------
  // In a real app you would fetch this from your API.
  // Here we just simulate a small sample – replace with your own fetch.
  const venuesGeoJSON = {
    type: "FeatureCollection",
    features: []   // will be filled after the fetch
  };

  // Example fetch (uncomment when you have a real endpoint)
  // const venuesUrl = "https://my-api.example.com/venues.geojson";
  // const venuesPromise = fetch(venuesUrl).then(r => r.json());

  // For the demo we generate random points (remove this block in production)
  const venuesPromise = new Promise(resolve => {
    const bounds = [-180, -85, 180, 85];
    for (let i = 0; i < 5000; i++) {
      const cat = categories[Math.floor(Math.random() * categories.length)];
      const lon = bounds[0] + Math.random() * (bounds[2] - bounds[0]);
      const lat = bounds[1] + Math.random() * (bounds[3] - bounds[1]);
      venuesGeoJSON.features.push({
        type: "Feature",
        geometry: { type: "Point", coordinates: [lon, lat] },
        properties: { category: cat, name: `${cat} #${i}` }
      });
    }
    resolve(venuesGeoJSON);
  });

  // --------------------------------------------------------------
  // 5️⃣ WHEN EVERYTHING IS READY – ADD SOURCE + LAYER
  // --------------------------------------------------------------
  Promise.all([...iconPromises, venuesPromise])
    .then(([_, geojson]) => {
      // 5‑a. Add the GeoJSON source
      map.addSource('venues', {
        type: 'geojson',
        data: geojson,
        // optional: enable client‑side clustering if you want even fewer icons at low zoom
        // cluster: true,
        // clusterMaxZoom: 14,
        // clusterRadius: 50
      });

      // 5‑b. Add the Symbol layer that uses the category icons
      map.addLayer({
        id: 'venue-icons',
        type: 'symbol',
        source: 'venues',
        layout: {
          // Pick the icon that matches the feature's `category` property
          'icon-image': ['get', 'category'],

          // Scale icons with zoom (feel free to tweak the numbers)
          'icon-size': [
            'interpolate',
            ['linear'],
            ['zoom'],
            5, 0.5,
            10, 0.8,
            15, 1.2
          ],

          // Do NOT allow icons to overlap; hide the ones that would collide
          'icon-allow-overlap': false,
          'icon-ignore-placement': false,
          'icon-optional': true,   // hide when there is no room

          // Optional: show a label underneath the icon
          // 'text-field': ['get', 'name'],
          // 'text-font': ['Open Sans Regular', 'Arial Unicode MS Regular'],
          // 'text-size': 12,
          // 'text-offset': [0, 1.2],
          // 'text-anchor': 'top',
          // 'text-allow-overlap': false,
          // 'text-ignore-placement': false,
          // 'text-optional': true
        },
        paint: {
          // If you set `sdf:true` when adding the image you can tint it here.
          // 'icon-color': '#ff6600',
          // 'text-color': '#222'
        }
      });
    })
    .catch(err => console.error('Error while initializing map:', err));

  // --------------------------------------------------------------
  // 6️⃣ OPTIONAL: Fit the map to the data once it loads
  // --------------------------------------------------------------
  map.on('load', () => {
    // Wait a tick for the source to be added (the Promise above resolves before `load` fires)
    setTimeout(() => {
      const source = map.getSource('venues');
      if (source && source._data && source._data.features.length) {
        const bounds = new maplibregl.LngLatBounds();
        source._data.features.forEach(f => bounds.extend(f.geometry.coordinates));
        map.fitBounds(bounds, { padding: 40, maxZoom: 14 });
      }
    }, 0);
  });
</script>
</body>
</html>
```

---

## What you need to adapt

| Part | What to change |
|------|----------------|
| **Map style / basemap** | Replace the simple OSM raster with your own vector style if you have one (`style: 'https://my-host/style.json'`). |
| **Icon URLs** | Update `https://my-cdn.example.com/icons/${cat}.svg` to point at the real location of your SVG files. |
| **Category list** | Fill the `categories` array with **exactly** the strings that appear in the `category` property of each venue (e.g. `"restaurant"`, `"cafe"`, …). |
| **GeoJSON source** | Swap the demo‑generator with a real `fetch('…/venues.geojson')` call (or any other way you obtain the data). |
| **Icon tinting** | If you want all icons to share a colour, keep `sdf:true` when adding the image and set `'icon-color'` in the layer’s `paint`. |
| **Labeling** | Uncomment the `text-*` layout/paint properties if you also want a name label under each icon. |
| **Clustering** | If you prefer classic point‑clustering (clusters become a single symbol at low zoom), uncomment the `cluster` options in the source and add a separate layer for clusters. |

---

### Quick checklist for “no pile‑up”

| Setting | Value | Reason |
|---------|-------|--------|
| `icon-allow-overlap` | `false` (default) | Prevents two icons from being drawn on top of each other. |
| `icon-ignore-placement` | `false` (default) | Makes the placement algorithm respect other symbols. |
| `icon-optional` | `true` | If an icon would collide, it is simply omitted – the map stays readable. |
| `icon-size` (by zoom) | `0.5 → 1.2` (example) | Smaller icons at low zoom reduce the chance of collisions. |
| **Optional** `text-optional: true` | Hide overlapping labels as well. |

That’s it! Load the page, the map will fetch all 40 + SVGs once, register them, pull in the 5 000 venue points, and render each point with its proper icon while automatically dropping
